FUNCTION_BLOCK FB_S03
VAR_INPUT
    DoorSwitch : BOOL;
    ZoneAOccupied : BOOL;
    ZoneBOccupied : BOOL;
    ResetBtn : BOOL;
    EStop_NC : BOOL;
END_VAR
VAR_OUTPUT
    DriveA_Run : BOOL;
    DriveB_Run : BOOL;
    AlarmLamp : BOOL;
    Status : WORD;
END_VAR
VAR
    ResetTrig : R_TRIG;
    BStopping : BOOL := FALSE;
    BStopCnt : INT := 0;
    StartLatched : BOOL := FALSE;
    ResetRequired : BOOL := FALSE;
    FirstScan : BOOL := TRUE;
END_VAR

(* 未提供“B 区动作完成”输入；按形式化规约以 500 ms / 25 扫描周期作为 B 区停止边界。 *)

IF FirstScan THEN
    DriveA_Run := FALSE;
    DriveB_Run := FALSE;
    AlarmLamp := FALSE;
    Status := 16#0000;
    BStopping := FALSE;
    BStopCnt := 0;
    StartLatched := FALSE;
    ResetRequired := FALSE;
    FirstScan := FALSE;
    ResetTrig(CLK := ResetBtn);
ELSE
    ResetTrig(CLK := ResetBtn);

    IF NOT EStop_NC THEN
        (* 急停最高优先级：两区立即停止，B 区 500 ms 延时取消 *)
        DriveA_Run := FALSE;
        DriveB_Run := FALSE;
        BStopping := FALSE;
        BStopCnt := 0;
        StartLatched := FALSE;
        ResetRequired := TRUE;
        AlarmLamp := TRUE;
        Status := 16#8303;
    ELSE
        IF DoorSwitch THEN
            (* 门开：A 区立即停止；B 区触发/继续停止延时 *)
            DriveA_Run := FALSE;
            IF DriveB_Run AND NOT BStopping THEN
                BStopping := TRUE;
                BStopCnt := 0;
            END_IF;

            IF BStopping THEN
                IF BStopCnt >= 25 THEN
                    DriveB_Run := FALSE;
                    BStopping := FALSE;
                    BStopCnt := 0;
                ELSE
                    BStopCnt := BStopCnt + 1;
                END_IF;
            END_IF;

            StartLatched := FALSE;
            ResetRequired := TRUE;
            AlarmLamp := TRUE;
            Status := 16#8302;
        ELSE
            (* 门关且无急停 *)
            IF ResetTrig.Q THEN
                ResetRequired := FALSE;
                StartLatched := TRUE;
            END_IF;

            IF BStopping THEN
                IF BStopCnt >= 25 THEN
                    DriveB_Run := FALSE;
                    BStopping := FALSE;
                    BStopCnt := 0;
                ELSE
                    BStopCnt := BStopCnt + 1;
                END_IF;

                IF StartLatched THEN
                    DriveA_Run := TRUE;
                ELSE
                    DriveA_Run := FALSE;
                END_IF;
                (* B 区在停止序列完成前保持运行；若本周期刚好完成，则已置 FALSE *)
            ELSE
                IF StartLatched THEN
                    DriveA_Run := TRUE;
                    DriveB_Run := TRUE;
                ELSE
                    DriveA_Run := FALSE;
                    DriveB_Run := FALSE;
                END_IF;
            END_IF;

            IF ResetRequired THEN
                AlarmLamp := FALSE;
                Status := 16#8301;
            ELSE
                AlarmLamp := FALSE;
                Status := 16#0000;
            END_IF;
        END_IF;
    END_IF;
END_IF;
END_FUNCTION_BLOCK
